mapper.select:
select aubr.*, case when aubr.operate_type = 0 then ifnull(km.name, cast(aubr.operate as char)) else cast(aubr.operate as char) end as operateName from aoc_user_bind_record aubr left join kf_manage km on aubr.operate = km.id and aubr.operate_type = 0
and aubr.aoc_user = #{reqVO.id}
order by aubr.id desc
